// CameraFollow.cs is generated by Gemini

using UnityEngine;

public class CameraFollow : MonoBehaviour
{
    [Tooltip("Drag your Player object here in the Inspector")]
    public Transform player;

    // Variables to lock the camera's X and Y positions
    private float lockedX;
    private float lockedY;
    
    // Keeps the initial distance between the camera and the player on the Z axis
    private float zOffset;

    void Start()
    {
        // Save the starting X and Y positions so they never change
        lockedX = transform.position.x;
        lockedY = transform.position.y;

        if (player != null)
        {
            // Calculate how far away the camera starts from the player on the Z axis
            zOffset = transform.position.z - player.position.z;
        }
        else
        {
            Debug.LogWarning("CameraFollow: Player is not assigned in the Inspector!");
        }
    }

    // LateUpdate runs after all Update functions, ensuring smooth camera movement
    void LateUpdate()
    {
        if (player != null)
        {
            // Calculate the new Z position to follow the player
            float targetZ = player.position.z + zOffset;
            
            // Move the camera, applying the locked X/Y and the new Z
            transform.position = new Vector3(lockedX, lockedY, targetZ);
        }
    }
}